public class RecursionTrap {
    public static void recursiveCounter(int count) {
        // Missing base case causes infinite stack frame accumulation
        System.out.println("Current depth: " + count);
        recursiveCounter(count + 1);
    }

    public static void main(String[] args) {
        try {
            recursiveCounter(1);
        } catch (StackOverflowError e) {
            System.err.println("Caught stack overflow at runtime!");
            // Note: Recovering state here is extremely risky due to partial stack frames
        }
    }
}
